param([Parameter(Mandatory)][string]$EvidenceFile,[Parameter(Mandatory)][string]$ObserverPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedObserverKeyId,[Parameter(Mandatory)][string]$ReleaseSigningPublicKeyFile,[switch]$AllowTestEvidence)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";. "$PSScriptRoot/GitHubGovernance.Common.ps1";$file=[IO.Path]::GetFullPath($EvidenceFile);$bytes=[IO.File]::ReadAllBytes($file);Test-BackupSignature $bytes ([IO.File]::ReadAllBytes("$file.observer.sig")) $ObserverPublicKeyFile 'GitHub governance observer';$observer=Get-BackupKeyFingerprint $ObserverPublicKeyFile 'GitHub governance observer' $false;$release=Get-BackupKeyFingerprint $ReleaseSigningPublicKeyFile 'Release signer' $false;if($observer-ceq$release){throw 'GitHub observer and release signer are not separated'};$evidence=$script:GitHubGovernanceUtf8.GetString($bytes)|ConvertFrom-Json -Depth 12 -DateKind String;if($evidence.ObserverKeyId-cne$ExpectedObserverKeyId-or$evidence.ObserverPublicKeySha256-cne$observer-or$evidence.ReleaseSigningPublicKeySha256-cne$release){throw 'GitHub governance signer identity is invalid'};Assert-GitHubProductionGovernance $evidence ([DateTimeOffset]::UtcNow) ([bool]$AllowTestEvidence);[ordered]@{Passed=$true;Owner=$evidence.Owner;Repository=$evidence.Repository;Branch=$evidence.Branch;CommitSha=$evidence.CommitSha;CheckRunId=$evidence.HostedCheck.CheckRunId;EvidenceSha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json
